import { defineLesson } from '../define';
import type { FlowNode, FlowState, Packet } from '../engines/flow';
import { patch } from '../engines/layouts';
import type { Frame } from '../types';

/*
 * Layout: callers on the left, the service in the middle, its dependency on the right.
 * The retry and circuit breaker frames are generated by running the notes' own code paths.
 */

const meter = (value: number, label: string) => ({ value, label, tone: value > 0.85 ? ('bad' as const) : value > 0.6 ? ('accent' as const) : ('ok' as const) });

/** A chain of hops where each hop starts as the previous one lands. */
function chain(ids: string[], label: string, delay = 0, tone: Packet['tone'] = 'req', dur = 0.6): Packet[] {
  return ids.slice(1).map((to, i) => ({ from: ids[i], to, label, tone, delay: delay + i * dur, dur }));
}

// Step 1: a slow dependency drains the caller's threads.
const BASIC: FlowNode[] = [
  { id: 'c', label: 'Client', kind: 'client', shape: 'laptop', x: 0, y: 1.6 },
  { id: 'svc', label: 'Service', sub: 'calls a dependency', kind: 'service', shape: 'server', x: 2.4, y: 1.6 },
  { id: 'dep', label: 'Dependency', sub: 'slow today', kind: 'db', x: 4.8, y: 1.6, status: 'hot', badge: { text: 'slow', tone: 'bad' } },
];
const BASIC_LINKS = [
  { from: 'c', to: 'svc' },
  { from: 'svc', to: 'dep' },
];

const drain = (busy: number): FlowState => ({
  nodes: patch(BASIC, { svc: { meter: meter(busy / 10, `threads ${busy}/10`), status: busy === 10 ? 'hot' : 'normal' } }),
  links: BASIC_LINKS,
  packets: [...chain(['c', 'svc', 'dep'], 'req', 0), ...chain(['c', 'svc', 'dep'], 'req', 0.35)],
  stats: [
    { label: 'Timeout', value: 'none', hint: 'library default: infinite', tone: 'bad' },
    { label: 'Threads busy', value: `${busy} / 10`, tone: busy === 10 ? 'bad' : 'neutral' },
    { label: 'Callers', value: busy === 10 ? 'stuck' : 'waiting', tone: busy === 10 ? 'bad' : 'neutral' },
  ],
  note: busy === 10 ? { text: 'every thread waits on the slow call: the caller is down too', tone: 'bad' } : undefined,
});

// Step 2: a deadline travels down the chain.
const DEADLINE_NODES: FlowNode[] = [
  { id: 'c', label: 'Client', kind: 'client', shape: 'laptop', x: 0, y: 1.6 },
  { id: 'gw', label: 'Gateway', kind: 'gateway', shape: 'gateway', x: 1.7, y: 1.6 },
  { id: 'svc', label: 'Service', kind: 'service', shape: 'server', x: 3.4, y: 1.6 },
  { id: 'db', label: 'Database', kind: 'db', shape: 'db', x: 5.1, y: 1.6 },
];
const DEADLINE_LINKS = [
  { from: 'c', to: 'gw' },
  { from: 'gw', to: 'svc' },
  { from: 'svc', to: 'db' },
];
const deadline = (hop: number): FlowState => {
  const left = ['300 ms left', '280 ms left', '120 ms left', 'deadline passed'];
  const ids = ['c', 'gw', 'svc', 'db'];
  const badges: Record<string, Partial<FlowNode>> = {};
  for (let i = 0; i <= hop; i++) badges[ids[i]] = { badge: { text: left[i], tone: i === 3 ? 'bad' : 'accent' } };
  if (hop === 3) {
    badges.db = { badge: { text: 'stop: caller gave up', tone: 'bad' } };
    badges.c = { badge: { text: 'timed out', tone: 'bad' } };
  }
  return {
    nodes: patch(DEADLINE_NODES, badges),
    links: DEADLINE_LINKS,
    packets:
      hop === 0
        ? [{ from: 'c', to: 'gw', label: 'deadline 300ms', dur: 0.6 }]
        : hop < 3
          ? [{ from: ids[hop - 1], to: ids[hop], label: 'deadline', dur: 0.6 }]
          : [{ from: 'svc', to: 'db', label: 'too late', tone: 'bad', dur: 0.6 }],
    stats: [
      { label: 'Deadline', value: '300 ms', hint: 'set by the caller' },
      { label: 'Timeout', value: 'p99 + a bit', hint: 'from observed latency' },
      { label: 'Wasted work', value: hop === 3 ? 'none' : '-', tone: hop === 3 ? 'ok' : 'neutral' },
    ],
    note: hop === 3 ? { text: 'downstream stops when the caller has given up', tone: 'accent' } : undefined,
  };
};

// Step 3: the notes' runnable retry, failing twice and succeeding on the third call.
function retryFrames(): Frame<FlowState>[] {
  const baseMs = 10;
  const capMs = 5000;
  const failUntil = 3;
  const frames: Frame<FlowState>[] = [];
  let calls = 0;
  for (let attempt = 0; ; attempt++) {
    calls++;
    const ok = calls >= failUntil;
    const ceiling = Math.min(capMs, baseMs * 2 ** attempt);
    frames.push({
      hold: 1900,
      state: {
        nodes: patch(BASIC, {
          dep: ok ? { status: 'normal', badge: { text: 'ok', tone: 'accent' }, sub: 'flaky' } : { status: 'hot', badge: { text: 'flaky', tone: 'bad' }, sub: 'flaky' },
          svc: { badge: { text: ok ? `ok after ${calls} calls` : `wait 0-${ceiling} ms`, tone: ok ? 'accent' : 'neutral' } },
        }),
        links: BASIC_LINKS,
        packets: [
          { from: 'svc', to: 'dep', label: `try ${attempt + 1}`, dur: 0.6 },
          { from: 'dep', to: 'svc', label: ok ? 'ok' : '503', tone: ok ? 'res' : 'bad', delay: 0.7, dur: 0.6 },
        ],
        stats: [
          { label: 'Attempt', value: String(attempt + 1) },
          { label: 'Backoff cap', value: `${ceiling} ms`, hint: 'min(cap, base x 2^n)' },
          { label: 'Jitter', value: 'full', hint: 'random 0..cap' },
        ],
        note: ok ? undefined : { text: 'random delay so retries from many callers do not line up', tone: 'accent' },
      },
    });
    if (ok) break;
  }
  frames.push({
    state: {
      nodes: patch(BASIC, { dep: { status: 'normal', badge: undefined, sub: 'healthy' }, svc: { badge: { text: 'no retry', tone: 'bad' } } }),
      links: BASIC_LINKS,
      packets: [
        { from: 'svc', to: 'dep', label: 'POST', dur: 0.6 },
        { from: 'dep', to: 'svc', label: '400', tone: 'bad', delay: 0.7, dur: 0.6 },
      ],
      stats: [
        { label: 'Retry on', value: 'timeout, 503', tone: 'ok' },
        { label: 'Never on', value: '400s', tone: 'bad' },
        { label: 'Only if', value: 'idempotent' },
      ],
      note: { text: 'a 400 will fail again: retrying only adds load', tone: 'bad' },
    },
  });
  return frames;
}

// Step 4: retries multiply across layers.
const LAYERS: FlowNode[] = [
  { id: 'c', label: 'Client', kind: 'client', shape: 'laptop', x: 0, y: 1.6 },
  { id: 'l1', label: 'Layer 1', kind: 'gateway', x: 1.45, y: 1.6 },
  { id: 'l2', label: 'Layer 2', kind: 'service', shape: 'server', x: 2.9, y: 1.6 },
  { id: 'l3', label: 'Layer 3', kind: 'service', shape: 'server', x: 4.35, y: 1.6 },
  { id: 'db', label: 'Database', kind: 'db', shape: 'db', x: 5.8, y: 1.6 },
];
const LAYER_LINKS = LAYERS.slice(1).map((n, i) => ({ from: LAYERS[i].id, to: n.id }));

function amplify(depth: number, oneLayer = false): FlowState {
  const tries = 3;
  const ids = ['l2', 'l3', 'db'];
  const seen = ids.map((_, i) => (oneLayer ? tries : tries ** (i + 1)));
  const changes: Record<string, Partial<FlowNode>> = {};
  ids.forEach((id, i) => {
    if (i <= depth) changes[id] = { badge: { text: `${seen[i]} calls`, tone: seen[i] > 9 ? 'bad' : 'neutral' }, status: seen[i] > 9 ? 'hot' : 'normal' };
  });
  if (oneLayer) changes.l1 = { badge: { text: 'retries here only', tone: 'accent' } };
  const from = ['l1', 'l2', 'l3'][depth];
  const to = ids[depth];
  const burst = Math.min(seen[depth], 6);
  return {
    nodes: patch(LAYERS, changes),
    links: LAYER_LINKS,
    packets: Array.from({ length: burst }, (_, k) => ({ from, to, delay: k * 0.18, dur: 0.6, tone: seen[depth] > 9 ? ('bad' as const) : ('req' as const) })),
    stats: [
      { label: 'Tries per layer', value: oneLayer ? '3, then 1' : '3' },
      { label: `Calls at ${LAYERS.find((n) => n.id === to)!.label}`, value: String(seen[depth]), tone: seen[depth] > 9 ? 'bad' : 'neutral' },
      { label: 'Retry budget', value: oneLayer ? '10%' : 'none', tone: oneLayer ? 'ok' : 'bad' },
    ],
    note: oneLayer
      ? { text: 'retry at one layer, with a budget of about 10% of requests', tone: 'accent' }
      : depth === 2
        ? { text: '3 x 3 x 3 = 27 calls from one user request', tone: 'bad' }
        : undefined,
  };
}

// Step 5: the notes' circuit breaker, run call by call.
const CB_NODES: FlowNode[] = [
  { id: 'svc', label: 'Service', kind: 'service', shape: 'server', x: 0.4, y: 1.6 },
  { id: 'cb', label: 'Breaker', sub: 'in the caller', kind: 'gateway', x: 2.6, y: 1.6 },
  { id: 'dep', label: 'Dependency', kind: 'db', x: 4.9, y: 1.6 },
];
const CB_LINKS = [
  { from: 'svc', to: 'cb' },
  { from: 'cb', to: 'dep' },
];

function breakerFrames(): Frame<FlowState>[] {
  const failureThreshold = 3;
  const resetMs = 200;
  let state: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  let failures = 0;
  let openedAt = 0;
  let now = 0;
  const frames: Frame<FlowState>[] = [];

  const call = (healthy: boolean, i: number | 'probe') => {
    let packets: Packet[];
    let note: FlowState['note'];
    let reached = true;
    if (state === 'OPEN' && now - openedAt < resetMs) {
      reached = false;
      packets = [
        { from: 'svc', to: 'cb', label: 'call', dur: 0.6 },
        { from: 'cb', to: 'svc', label: 'fail fast', tone: 'bad', delay: 0.65, dur: 0.6 },
      ];
      note = { text: 'open: fail immediately, the dependency gets room to recover', tone: 'accent' };
    } else {
      if (state === 'OPEN') state = 'HALF_OPEN';
      const probing = state === 'HALF_OPEN';
      if (healthy) {
        state = 'CLOSED';
        failures = 0;
      } else {
        failures++;
        if (probing || failures >= failureThreshold) {
          state = 'OPEN';
          openedAt = now;
        }
      }
      packets = [
        ...chain(['svc', 'cb', 'dep'], probing ? 'probe' : 'call', 0),
        ...chain(['dep', 'cb', 'svc'], healthy ? 'recovered' : 'down', 1.3, healthy ? 'res' : 'bad'),
      ];
      if (probing) note = { text: 'half-open: one probe got through and succeeded', tone: 'accent' };
      else if (state === 'OPEN') note = { text: `${failures} failures hit the threshold: trip open`, tone: 'bad' };
    }
    frames.push({
      hold: reached ? 2800 : 1700,
      state: {
        nodes: patch(CB_NODES, {
          cb: { badge: { text: state, tone: state === 'OPEN' ? 'bad' : 'accent' }, status: state === 'OPEN' ? 'hot' : 'normal' },
          dep: healthy ? { badge: { text: 'healthy again', tone: 'accent' } } : { status: 'down', badge: { text: 'down', tone: 'bad' } },
        }),
        links: CB_LINKS.map((l) => (l.to === 'dep' && state === 'OPEN' ? { ...l, dashed: true, tone: 'bad' as const } : l)),
        packets,
        stats: [
          { label: 'Call', value: i === 'probe' ? 'after 250 ms' : String(i + 1) },
          { label: 'Failures', value: `${failures} / ${failureThreshold}`, tone: failures >= failureThreshold ? 'bad' : 'neutral' },
          { label: 'Reset after', value: `${resetMs} ms` },
        ],
        note,
      },
    });
  };

  for (let i = 0; i < 5; i++) call(false, i);
  now += 250;
  call(true, 'probe');
  return frames;
}

// Step 6: bulkheads.
const bulkhead = (split: boolean): FlowState => {
  const pools: FlowNode[] = split
    ? [
        { id: 'pp', label: 'Pay pool', sub: '5 threads', kind: 'worker', x: 2.5, y: 0.6, status: 'hot', meter: meter(1, '5/5 busy') },
        { id: 'sp', label: 'Search pool', sub: '5 threads', kind: 'worker', x: 2.5, y: 2.6, meter: meter(0.4, '2/5 busy') },
      ]
    : [{ id: 'pool', label: 'Shared pool', sub: '10 threads', kind: 'worker', x: 2.5, y: 1.6, status: 'hot', meter: meter(1, '10/10 busy') }];
  const pay = split ? 'pp' : 'pool';
  const search = split ? 'sp' : 'pool';
  return {
    nodes: [
      { id: 'c', label: 'Service', kind: 'service', shape: 'server', x: 0.3, y: 1.6 },
      ...pools,
      { id: 'pay', label: 'Payments', sub: 'slow', kind: 'external', shape: 'cloud', x: 4.9, y: 0.6, status: 'hot' },
      { id: 'srch', label: 'Search', sub: 'healthy', kind: 'search', x: 4.9, y: 2.6 },
    ],
    links: [
      { from: 'c', to: pay },
      ...(split ? [{ from: 'c', to: search }] : []),
      { from: pay, to: 'pay' },
      { from: search, to: 'srch' },
    ],
    packets: split
      ? [...chain(['c', 'sp', 'srch'], 'search', 0, 'req'), ...chain(['srch', 'sp', 'c'], 'ok', 1.3, 'res')]
      : [...chain(['c', 'pool'], 'search', 0, 'req'), { from: 'pool', to: 'c', label: 'no thread', tone: 'bad', delay: 0.7, dur: 0.6 }],
    stats: [
      { label: 'Pools', value: split ? '1 per dep' : '1 shared', tone: split ? 'ok' : 'bad' },
      { label: 'Payments', value: 'slow', tone: 'bad' },
      { label: 'Search', value: split ? 'works' : 'starved', tone: split ? 'ok' : 'bad' },
    ],
    note: split ? { text: 'the slow dependency can only drain its own pool', tone: 'accent' } : { text: 'one slow dependency drained every thread', tone: 'bad' },
  };
};

// Step 7: a metastable failure: retries keep the system slow after the trigger is gone.
const CALLERS: FlowNode[] = [
  { id: 'c1', label: 'Client', kind: 'client', shape: 'laptop', x: 0, y: 0.5, size: 'sm' },
  { id: 'c2', label: 'Client', kind: 'client', shape: 'laptop', x: 0, y: 1.6, size: 'sm' },
  { id: 'c3', label: 'Client', kind: 'client', shape: 'laptop', x: 0, y: 2.7, size: 'sm' },
];
const meta = (phase: 'trigger' | 'stuck' | 'shed' | 'recovered'): FlowState => {
  const load = { trigger: 0.8, stuck: 1, shed: 0.65, recovered: 0.4 }[phase];
  const retries = phase === 'trigger' || phase === 'stuck';
  const packets: Packet[] = CALLERS.flatMap((c, i) => {
    const base: Packet[] = [{ from: c.id, to: 'svc', delay: i * 0.2, dur: 0.6 }];
    if (retries) base.push({ from: c.id, to: 'svc', label: 'retry', tone: 'bad', delay: 0.7 + i * 0.2, dur: 0.6 });
    return base;
  });
  if (phase === 'shed') packets.push({ from: 'svc', to: 'c3', label: '503', tone: 'bad', delay: 0.9, dur: 0.6 });
  const badge = {
    trigger: { text: 'brief slowdown', tone: 'bad' as const },
    stuck: { text: 'trigger gone, still slow', tone: 'bad' as const },
    shed: { text: 'shedding low priority', tone: 'accent' as const },
    recovered: { text: 'recovered', tone: 'accent' as const },
  }[phase];
  return {
    nodes: [
      ...CALLERS,
      { id: 'svc', label: 'Service', kind: 'service', shape: 'server', x: 3.2, y: 1.6, status: load >= 0.8 ? 'hot' : 'normal', badge, meter: meter(load, `load ${Math.round(load * 100)}%`) },
    ],
    links: CALLERS.map((c) => ({ from: c.id, to: 'svc' })),
    packets,
    stats: [
      { label: 'Trigger', value: phase === 'trigger' ? 'active' : 'gone', tone: phase === 'trigger' ? 'bad' : 'ok' },
      { label: 'Retries', value: retries ? 'unbounded' : 'budgeted', tone: retries ? 'bad' : 'ok' },
      { label: 'Load', value: `${Math.round(load * 100)}%`, tone: load >= 0.8 ? 'bad' : 'ok' },
    ],
    note: {
      trigger: { text: 'clients time out and retry: the retries add load', tone: 'bad' as const },
      stuck: { text: 'the extra load keeps it slow, so it never recovers', tone: 'bad' as const },
      shed: { text: 'retry budget plus load shedding break the loop', tone: 'accent' as const },
      recovered: { text: 'ramp traffic back slowly, keep headroom', tone: 'ok' as const },
    }[phase],
  };
};

// Step 8: the whole call path from the notes' flowchart.
const RECAP: FlowState = {
  nodes: [
    { id: 'call', label: 'Caller', sub: 'deadline set', kind: 'client', shape: 'laptop', x: 0, y: 1.1 },
    { id: 'cb', label: 'Breaker', sub: 'open? fail fast', kind: 'gateway', x: 1.6, y: 1.1 },
    { id: 'bh', label: 'Bulkhead', sub: 'limited pool', kind: 'worker', x: 3.2, y: 1.1 },
    { id: 'dep', label: 'Dependency', sub: 'with a timeout', kind: 'db', x: 4.8, y: 1.1 },
    { id: 'rt', label: 'Retry', sub: 'budget + jitter', kind: 'queue', shape: 'queue', x: 4.0, y: 2.7 },
    { id: 'fb', label: 'Fallback', sub: 'cached or error', kind: 'cache', x: 1.6, y: 2.7 },
  ],
  links: [
    { from: 'call', to: 'cb' },
    { from: 'cb', to: 'bh' },
    { from: 'bh', to: 'dep' },
    { from: 'dep', to: 'rt', dashed: true, label: 'failure' },
    { from: 'rt', to: 'fb', dashed: true, label: 'no budget' },
    { from: 'cb', to: 'fb', dashed: true, tone: 'bad' },
  ],
  packets: [...chain(['call', 'cb', 'bh', 'dep'], 'call', 0), ...chain(['dep', 'bh', 'cb', 'call'], 'ok', 1.9, 'res')],
  stats: [
    { label: 'Every call', value: 'timeout' },
    { label: 'Retries', value: 'one layer' },
    { label: 'Breaker', value: '3 states' },
  ],
};

const CB = breakerFrames();

export default defineLesson('flow', {
  slug: 'resilience',
  objectives: [
    { text: 'Why every network call needs a timeout and a propagated deadline', step: 2 },
    { text: 'Retry safely: idempotent calls, backoff with jitter, one layer, a budget', step: 4 },
    { text: 'How a circuit breaker moves between closed, open and half-open', step: 5 },
    { text: 'Contain damage with bulkheads and load shedding', step: 6 },
    { text: 'Recognise a metastable failure and how to escape it', step: 7 },
  ],
  steps: [
    {
      label: 'The problem',
      title: 'One slow dependency, one dead service',
      tag: 'problem',
      body: [
        'Assume every dependency will be slow or broken. Here the dependency is only slow, yet the service calling it has no timeout. The default in many libraries is **infinite**.',
        'Each request parks a thread on the slow call until none are left.',
      ],
      keyIdea: 'Resilience patterns exist to keep one failure from becoming an outage.',
      frames: [
        { state: drain(3), hold: 1500 },
        { state: drain(7), hold: 1500 },
        { state: drain(10) },
      ],
    },
    {
      label: 'Deadlines',
      title: 'Timeouts and deadlines',
      tag: 'concept',
      body: [
        'Every network call needs a **timeout**. Set it from observed latency, a bit above the p99.',
        'Better still, propagate a **deadline** down the chain. Each hop sees how much time is left, so downstream work stops once the caller has given up.',
      ],
      keyIdea: 'A timeout protects one call. A deadline protects the whole chain from doing work nobody is waiting for.',
      frames: [0, 1, 2, 3].map((h) => ({ state: deadline(h), hold: h === 3 ? undefined : 1300 })),
    },
    {
      label: 'Retries',
      title: 'Retry with backoff and jitter',
      tag: 'technique',
      body: [
        'Retry only **idempotent** operations, and only on retryable errors such as timeouts and 503, never on 400s.',
        'Wait longer each time: the cap doubles from a base of 10 ms, and **full jitter** picks a random delay below it so callers do not retry in lockstep.',
      ],
      keyIdea: 'Exponential backoff spaces retries out, jitter spreads them apart. Both stop retries from becoming a synchronized spike.',
      frames: retryFrames(),
    },
    {
      label: 'Amplification',
      title: 'Retries multiply across layers',
      tag: 'trade-off',
      body: [
        'If each of 3 layers tries 3 times, one user request becomes **27 calls** at the bottom, exactly when that dependency is struggling.',
        'Retry at **one layer only**, and cap retries with a **retry budget**, for example at most 10% of requests.',
      ],
      keyIdea: 'Retries help with blips and hurt during overload. Budget them and keep them in one place.',
      frames: [
        { state: amplify(0), hold: 1700 },
        { state: amplify(1), hold: 1900 },
        { state: amplify(2), hold: 2400 },
        { state: amplify(2, true) },
      ],
    },
    {
      label: 'Breaker',
      title: 'Circuit breaker: stop calling a dead dependency',
      tag: 'technique',
      body: [
        'Count failures. After **3** the breaker trips **open** and calls fail immediately, which frees your threads and gives the dependency room to recover.',
        'After the reset timeout (200 ms here) it goes **half-open** and lets a probe through. Success closes it, failure opens it again.',
      ],
      keyIdea: 'Closed counts failures, open fails fast, half-open probes. Production breakers track a failure rate over a window and allow one probe at a time.',
      frames: CB,
    },
    {
      label: 'Bulkheads',
      title: 'Bulkheads keep failures in their lane',
      tag: 'technique',
      body: [
        'With one shared thread pool, slow Payments calls use every thread and healthy Search calls starve.',
        'A **bulkhead** gives each dependency its own pool or connection limit, so a slow one can only drain its own.',
      ],
      keyIdea: 'Isolate resources per dependency. Pair it with graceful degradation: cached data or no recommendations beats an error page.',
      frames: [
        { state: bulkhead(false), hold: 2600 },
        { state: bulkhead(true) },
      ],
    },
    {
      label: 'Metastable',
      title: 'Stuck after the trigger is gone',
      tag: 'trade-off',
      body: [
        'A brief slowdown makes clients time out and retry. The retries add load, the load keeps the system slow, and it **never recovers** on its own.',
        'Defences: retry budgets, **load shedding** (reject low priority work early with a 503), circuit breakers, capacity headroom, and ramping traffic back slowly.',
      ],
      keyIdea: 'Removing the trigger is not enough. You must remove the extra load that keeps the bad state alive.',
      frames: [
        { state: meta('trigger'), hold: 2200 },
        { state: meta('stuck'), hold: 2200 },
        { state: meta('shed'), hold: 2200 },
        { state: meta('recovered') },
      ],
    },
    {
      label: 'Recap',
      title: 'The defended call path',
      tag: 'recap',
      body: [
        '- **Timeouts:** on every call, a bit above p99, with a deadline propagated downstream.',
        '- **Retries:** idempotent only, retryable errors only, exponential backoff with jitter, one layer, a budget.',
        '- **Circuit breaker:** closed, open, half-open. Fail fast while the dependency recovers.',
        '- **Bulkheads and shedding:** separate pools per dependency, reject low priority work under overload.',
        '- **Metastable failures:** the retry loop can outlive its trigger. Shed load and ramp back slowly.',
      ],
      keyIdea: 'Assume every dependency will be slow or broken, and decide in advance what each call does when it is.',
      frames: [{ state: RECAP }],
    },
  ],
});
